-- V1__schema.sql
-- Baseline schema of the Sigyll CA database: the CA model (SigyllDbContext) and the operator
-- sign-in tables (ASP.NET Core Identity, SigyllAuthDbContext). Generated from the EF Core model
-- on 2026-10-22, when schema ownership moved from EF migrations to Flyway; later changes are new
-- V files. Identifiers are quoted PascalCase to match the EF Core model. Privileges live in
-- V0__schema_privileges.sql.

CREATE TABLE "CertificateProfiles" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Description" TEXT,
    "CertificateType" SMALLINT NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "KeySize" INTEGER NOT NULL,
    "ValidityDays" INTEGER NOT NULL,
    "KeyUsageFlags" INTEGER NOT NULL,
    "IsKeyUsageCritical" BOOLEAN NOT NULL,
    "ExtendedKeyUsageOids" TEXT,
    "IsBasicConstraintsCa" BOOLEAN NOT NULL,
    "IsBasicConstraintsCritical" BOOLEAN NOT NULL,
    "PathLengthConstraint" INTEGER,
    "IsExtendedKeyUsageCritical" BOOLEAN NOT NULL,
    "EcdsaCurve" CHARACTER VARYING(20),
    "HashAlgorithm" CHARACTER VARYING(10) NOT NULL,
    "SubjectTemplate" CHARACTER VARYING(500),
    "IncludeCdp" BOOLEAN NOT NULL,
    "CdpUrlTemplate" CHARACTER VARYING(500),
    "IncludeAia" BOOLEAN NOT NULL,
    "AiaUrlTemplate" CHARACTER VARYING(500),
    "SubjectAltNameTypes" CHARACTER VARYING(100),
    "IsPreset" BOOLEAN NOT NULL,
    "AllowAutoIssue" BOOLEAN NOT NULL,
    "RequiresRaApproval" BOOLEAN NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_CertificateProfiles" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "CertificateProfiles" IS 'Certificate profiles (RFC 3647 section 7.1): reusable definitions of what an issued certificate contains';

COMMENT ON COLUMN "CertificateProfiles"."Id" IS 'Primary key';

COMMENT ON COLUMN "CertificateProfiles"."Name" IS 'Unique profile name shown when issuing';

COMMENT ON COLUMN "CertificateProfiles"."Description" IS 'What the profile is for';

COMMENT ON COLUMN "CertificateProfiles"."CertificateType" IS '0 RootCa, 1 IntermediateCa, 2 EndEntityClient, 3 EndEntityServer';

COMMENT ON COLUMN "CertificateProfiles"."KeyAlgorithm" IS 'Key algorithm, e.g. RSA, ECDSA, ML-DSA-87, ML-KEM-1024';

COMMENT ON COLUMN "CertificateProfiles"."KeySize" IS 'Key size in bits for RSA; parameter set number for post-quantum algorithms';

COMMENT ON COLUMN "CertificateProfiles"."ValidityDays" IS 'Default validity period in days';

COMMENT ON COLUMN "CertificateProfiles"."KeyUsageFlags" IS 'X.509 key usage bit flags (System.Security.Cryptography.X509Certificates.X509KeyUsageFlags)';

COMMENT ON COLUMN "CertificateProfiles"."IsKeyUsageCritical" IS 'Whether the key usage extension is marked critical';

COMMENT ON COLUMN "CertificateProfiles"."ExtendedKeyUsageOids" IS 'Semicolon-delimited extended key usage OIDs, e.g. 1.3.6.1.5.5.7.3.2';

COMMENT ON COLUMN "CertificateProfiles"."IsBasicConstraintsCa" IS 'Whether basic constraints marks the certificate as a CA';

COMMENT ON COLUMN "CertificateProfiles"."IsBasicConstraintsCritical" IS 'Whether the basic constraints extension is marked critical';

COMMENT ON COLUMN "CertificateProfiles"."PathLengthConstraint" IS 'Basic constraints path length for CA certificates; null for no limit';

COMMENT ON COLUMN "CertificateProfiles"."IsExtendedKeyUsageCritical" IS 'Whether the extended key usage extension is marked critical';

COMMENT ON COLUMN "CertificateProfiles"."EcdsaCurve" IS 'nistP256, nistP384 or nistP521; only used when KeyAlgorithm is ECDSA';

COMMENT ON COLUMN "CertificateProfiles"."HashAlgorithm" IS 'Signature hash algorithm, e.g. SHA256; Pure for ML-DSA and SLH-DSA';

COMMENT ON COLUMN "CertificateProfiles"."SubjectTemplate" IS 'Subject DN pattern pre-filled when issuing';

COMMENT ON COLUMN "CertificateProfiles"."IncludeCdp" IS 'Whether issued certificates carry a CRL distribution point';

COMMENT ON COLUMN "CertificateProfiles"."CdpUrlTemplate" IS 'CRL URL pattern; {BaseUrl} and {CAName} are expanded at issuance. Null uses {BaseUrl}/crls/{CAName}.crl';

COMMENT ON COLUMN "CertificateProfiles"."IncludeAia" IS 'Whether issued certificates carry an authority information access (CA issuers) URL';

COMMENT ON COLUMN "CertificateProfiles"."AiaUrlTemplate" IS 'CA issuers URL pattern; {BaseUrl} and {CAName} are expanded at issuance. Null uses {BaseUrl}/certs/{CAName}.cer';

COMMENT ON COLUMN "CertificateProfiles"."SubjectAltNameTypes" IS 'Semicolon-delimited SAN types (URI;DNS;Email;IP); each listed type is required at issuance';

COMMENT ON COLUMN "CertificateProfiles"."IsPreset" IS 'System-seeded profile that cannot be deleted, only cloned';

COMMENT ON COLUMN "CertificateProfiles"."AllowAutoIssue" IS 'Portal policy: requests for this profile may be issued automatically after domain validation';

COMMENT ON COLUMN "CertificateProfiles"."RequiresRaApproval" IS 'Portal policy: requests for this profile always need human RA approval';

COMMENT ON COLUMN "CertificateProfiles"."CreatedAt" IS 'When the profile was created (UTC)';

CREATE TABLE "CredentialSchemas" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Description" TEXT,
    "TypeUri" CHARACTER VARYING(500),
    "Format" CHARACTER VARYING(50) NOT NULL,
    "ClaimsSchemaJson" TEXT NOT NULL,
    "DefaultValidityDays" INTEGER,
    "IsPreset" BOOLEAN NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_CredentialSchemas" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "CredentialSchemas" IS 'Verifiable Credential schemas: the claims a credential type may carry';

COMMENT ON COLUMN "CredentialSchemas"."Id" IS 'Primary key';

COMMENT ON COLUMN "CredentialSchemas"."Name" IS 'Unique schema name';

COMMENT ON COLUMN "CredentialSchemas"."Description" IS 'What the credential attests';

COMMENT ON COLUMN "CredentialSchemas"."TypeUri" IS 'Optional VC type URI added to the credential type array';

COMMENT ON COLUMN "CredentialSchemas"."Format" IS 'Securing format, e.g. jwt_vc';

COMMENT ON COLUMN "CredentialSchemas"."ClaimsSchemaJson" IS 'JSON Schema describing the required and permitted credentialSubject claims';

COMMENT ON COLUMN "CredentialSchemas"."DefaultValidityDays" IS 'Default credential validity in days';

COMMENT ON COLUMN "CredentialSchemas"."IsPreset" IS 'System-seeded schema that cannot be deleted';

COMMENT ON COLUMN "CredentialSchemas"."CreatedAt" IS 'When the schema was created (UTC)';

CREATE TABLE "DidTemplates" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Description" TEXT,
    "Method" CHARACTER VARYING(50) NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "EcdsaCurve" CHARACTER VARYING(20),
    "DefaultPurposes" CHARACTER VARYING(200) NOT NULL,
    "IsPreset" BOOLEAN NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_DidTemplates" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "DidTemplates" IS 'DID templates: method and key settings used to create DID documents';

COMMENT ON COLUMN "DidTemplates"."Id" IS 'Primary key';

COMMENT ON COLUMN "DidTemplates"."Name" IS 'Unique template name';

COMMENT ON COLUMN "DidTemplates"."Description" IS 'What the template is for';

COMMENT ON COLUMN "DidTemplates"."Method" IS 'DID method, e.g. key, web, jwk';

COMMENT ON COLUMN "DidTemplates"."KeyAlgorithm" IS 'Key algorithm, e.g. Ed25519 or ECDSA';

COMMENT ON COLUMN "DidTemplates"."EcdsaCurve" IS 'nistP256, nistP384 or nistP521; only used when KeyAlgorithm is ECDSA';

COMMENT ON COLUMN "DidTemplates"."DefaultPurposes" IS 'Semicolon-delimited verification method purposes, e.g. assertionMethod;authentication';

COMMENT ON COLUMN "DidTemplates"."IsPreset" IS 'System-seeded template that cannot be deleted';

COMMENT ON COLUMN "DidTemplates"."CreatedAt" IS 'When the template was created (UTC)';

CREATE TABLE "RecurringJobs" (
    "Id" CHARACTER VARYING(100) NOT NULL,
    "Cron" CHARACTER VARYING(100) NOT NULL,
    "Enabled" BOOLEAN NOT NULL,
    "NextRunAt" TIMESTAMP WITH TIME ZONE,
    "LastRunAt" TIMESTAMP WITH TIME ZONE,
    "LastResult" CHARACTER VARYING(20),
    "LastError" TEXT,
    "LastDurationMs" INTEGER,
    "UpdatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_RecurringJobs" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "RecurringJobs" IS 'Schedule and last outcome of each recurring background job, e.g. CRL auto-renewal';

COMMENT ON COLUMN "RecurringJobs"."Id" IS 'Stable job key, e.g. crl-auto-renewal (primary key)';

COMMENT ON COLUMN "RecurringJobs"."Cron" IS 'Five-field cron expression, evaluated in UTC';

COMMENT ON COLUMN "RecurringJobs"."Enabled" IS 'Whether the job runs on its schedule';

COMMENT ON COLUMN "RecurringJobs"."NextRunAt" IS 'When the job is next due (UTC); Run Now sets it to the current time';

COMMENT ON COLUMN "RecurringJobs"."LastRunAt" IS 'When the job last finished (UTC)';

COMMENT ON COLUMN "RecurringJobs"."LastResult" IS 'Outcome of the last run: Succeeded or Failed';

COMMENT ON COLUMN "RecurringJobs"."LastError" IS 'Error message from the last failed run';

COMMENT ON COLUMN "RecurringJobs"."LastDurationMs" IS 'Duration of the last run in milliseconds';

COMMENT ON COLUMN "RecurringJobs"."UpdatedAt" IS 'When the row last changed (UTC)';

CREATE TABLE "SanLists" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Description" TEXT,
    "Items" TEXT NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_SanLists" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "SanLists" IS 'Reusable lists of subject alternative names attached to certificate profiles';

COMMENT ON COLUMN "SanLists"."Id" IS 'Primary key';

COMMENT ON COLUMN "SanLists"."Name" IS 'Unique list name';

COMMENT ON COLUMN "SanLists"."Description" IS 'What the list is for';

COMMENT ON COLUMN "SanLists"."Items" IS 'Semicolon-delimited SAN entries, e.g. URI:urn:oid:...;DNS:example.com';

COMMENT ON COLUMN "SanLists"."CreatedAt" IS 'When the list was created (UTC)';

CREATE TABLE "TrustDomains" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Description" TEXT,
    "CrlValidityDays" INTEGER NOT NULL,
    "Enabled" BOOLEAN NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_TrustDomains" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "TrustDomains" IS 'Trust domains (NIST SP 800-32): groups of CA hierarchies sharing publication base URLs and a repository';

COMMENT ON COLUMN "TrustDomains"."Id" IS 'Primary key';

COMMENT ON COLUMN "TrustDomains"."Name" IS 'Unique trust domain name';

COMMENT ON COLUMN "TrustDomains"."Description" IS 'What the trust domain is for';

COMMENT ON COLUMN "TrustDomains"."CrlValidityDays" IS 'Default validity of CRLs issued by the domain''s CAs, in days';

COMMENT ON COLUMN "TrustDomains"."Enabled" IS 'Whether the trust domain is in use';

COMMENT ON COLUMN "TrustDomains"."CreatedAt" IS 'When the trust domain was created (UTC)';

CREATE TABLE "CertificateProfileSanList" (
    "ProfilesId" INTEGER NOT NULL,
    "SanListsId" INTEGER NOT NULL,
    CONSTRAINT "PK_CertificateProfileSanList" PRIMARY KEY ("ProfilesId", "SanListsId"),
    CONSTRAINT "FK_CertificateProfileSanList_CertificateProfiles_ProfilesId" FOREIGN KEY ("ProfilesId") REFERENCES "CertificateProfiles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CertificateProfileSanList_SanLists_SanListsId" FOREIGN KEY ("SanListsId") REFERENCES "SanLists" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "CertificateProfileSanList" IS 'Join table: SAN lists attached to certificate profiles';

COMMENT ON COLUMN "CertificateProfileSanList"."ProfilesId" IS 'Certificate profile (CertificateProfiles.Id)';

COMMENT ON COLUMN "CertificateProfileSanList"."SanListsId" IS 'SAN list (SanLists.Id)';

CREATE TABLE "CaCertificates" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "TrustDomainId" INTEGER NOT NULL,
    "ParentId" INTEGER,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Subject" CHARACTER VARYING(500) NOT NULL,
    "X509CertificatePem" TEXT NOT NULL,
    "EncryptedPfxBytes" BYTEA,
    "PfxPassword" TEXT,
    "Thumbprint" CHARACTER VARYING(64) NOT NULL,
    "SerialNumber" CHARACTER VARYING(100) NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "KeySize" INTEGER NOT NULL,
    "NotBefore" TIMESTAMP WITH TIME ZONE NOT NULL,
    "NotAfter" TIMESTAMP WITH TIME ZONE NOT NULL,
    "CrlDistributionPoint" TEXT,
    "AuthorityInfoAccessUri" TEXT,
    "CertSecurityLevel" SMALLINT NOT NULL,
    "StoreProviderHint" CHARACTER VARYING(200),
    "IsRevoked" BOOLEAN NOT NULL,
    "RevokedAt" TIMESTAMP WITH TIME ZONE,
    "RevocationReason" INTEGER NOT NULL,
    "Version" INTEGER NOT NULL,
    "RenewalOfId" INTEGER,
    "Enabled" BOOLEAN NOT NULL,
    "AutoRenew" BOOLEAN NOT NULL,
    "IsArchived" BOOLEAN NOT NULL,
    "ArchivedAt" TIMESTAMP WITH TIME ZONE,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_CaCertificates" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CaCertificates_CaCertificates_ParentId" FOREIGN KEY ("ParentId") REFERENCES "CaCertificates" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_CaCertificates_CaCertificates_RenewalOfId" FOREIGN KEY ("RenewalOfId") REFERENCES "CaCertificates" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_CaCertificates_TrustDomains_TrustDomainId" FOREIGN KEY ("TrustDomainId") REFERENCES "TrustDomains" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "CaCertificates" IS 'Root and intermediate CA certificates with their keys or key references';

COMMENT ON COLUMN "CaCertificates"."Id" IS 'Primary key';

COMMENT ON COLUMN "CaCertificates"."TrustDomainId" IS 'Owning trust domain (TrustDomains.Id)';

COMMENT ON COLUMN "CaCertificates"."ParentId" IS 'Issuing CA for intermediates (CaCertificates.Id); null for root CAs';

COMMENT ON COLUMN "CaCertificates"."Name" IS 'Display name, unique within the trust domain';

COMMENT ON COLUMN "CaCertificates"."Subject" IS 'Subject distinguished name';

COMMENT ON COLUMN "CaCertificates"."X509CertificatePem" IS 'The certificate, PEM encoded';

COMMENT ON COLUMN "CaCertificates"."EncryptedPfxBytes" IS 'PKCS#12 holding the private key (AES-256), for locally held keys; null for remote keys';

COMMENT ON COLUMN "CaCertificates"."PfxPassword" IS 'Password of EncryptedPfxBytes';

COMMENT ON COLUMN "CaCertificates"."Thumbprint" IS 'SHA-1 thumbprint, upper-case hex';

COMMENT ON COLUMN "CaCertificates"."SerialNumber" IS 'Serial number, hex';

COMMENT ON COLUMN "CaCertificates"."KeyAlgorithm" IS 'Key algorithm, e.g. RSA, ECDSA, ML-DSA-87';

COMMENT ON COLUMN "CaCertificates"."KeySize" IS 'Key size in bits for RSA; parameter set number for post-quantum algorithms';

COMMENT ON COLUMN "CaCertificates"."NotBefore" IS 'Start of validity (UTC)';

COMMENT ON COLUMN "CaCertificates"."NotAfter" IS 'End of validity (UTC)';

COMMENT ON COLUMN "CaCertificates"."CrlDistributionPoint" IS 'CRL distribution point URL carried in the certificate';

COMMENT ON COLUMN "CaCertificates"."AuthorityInfoAccessUri" IS 'CA issuers URL carried in the certificate';

COMMENT ON COLUMN "CaCertificates"."CertSecurityLevel" IS 'Where the key lives: 0 Software, 1 Fips1403 (HSM), 2 CloudKms';

COMMENT ON COLUMN "CaCertificates"."StoreProviderHint" IS 'Signing provider and key id for remote keys, e.g. vault-transit:sigil-rsa-4096';

COMMENT ON COLUMN "CaCertificates"."IsRevoked" IS 'Whether the CA certificate has been revoked';

COMMENT ON COLUMN "CaCertificates"."RevokedAt" IS 'When it was revoked (UTC)';

COMMENT ON COLUMN "CaCertificates"."RevocationReason" IS 'CRL reason code (RFC 5280 section 5.3.1)';

COMMENT ON COLUMN "CaCertificates"."Version" IS '1-based renewal generation within this CA lineage; incremented on each re-key';

COMMENT ON COLUMN "CaCertificates"."RenewalOfId" IS 'CA certificate this one renewed (CaCertificates.Id); null for the first issuance';

COMMENT ON COLUMN "CaCertificates"."Enabled" IS 'Whether the CA may issue';

COMMENT ON COLUMN "CaCertificates"."AutoRenew" IS 'Whether the CA is renewed automatically before expiry; off means left to expire on purpose';

COMMENT ON COLUMN "CaCertificates"."IsArchived" IS 'Hidden from the explorer but kept for history';

COMMENT ON COLUMN "CaCertificates"."ArchivedAt" IS 'When it was archived (UTC)';

COMMENT ON COLUMN "CaCertificates"."CreatedAt" IS 'When the row was created (UTC)';

CREATE TABLE "DidDocuments" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "TrustDomainId" INTEGER NOT NULL,
    "DidTemplateId" INTEGER,
    "Did" CHARACTER VARYING(500) NOT NULL,
    "Method" CHARACTER VARYING(50) NOT NULL,
    "Deactivated" BOOLEAN NOT NULL,
    "DeactivatedAt" TIMESTAMP WITH TIME ZONE,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_DidDocuments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DidDocuments_DidTemplates_DidTemplateId" FOREIGN KEY ("DidTemplateId") REFERENCES "DidTemplates" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_DidDocuments_TrustDomains_TrustDomainId" FOREIGN KEY ("TrustDomainId") REFERENCES "TrustDomains" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "DidDocuments" IS 'DID documents created by Sigyll';

COMMENT ON COLUMN "DidDocuments"."Id" IS 'Primary key';

COMMENT ON COLUMN "DidDocuments"."TrustDomainId" IS 'Owning trust domain (TrustDomains.Id)';

COMMENT ON COLUMN "DidDocuments"."DidTemplateId" IS 'Template used to create it (DidTemplates.Id); null if the template was deleted';

COMMENT ON COLUMN "DidDocuments"."Did" IS 'The full DID, e.g. did:key:z6Mk...';

COMMENT ON COLUMN "DidDocuments"."Method" IS 'DID method, e.g. key, web, jwk';

COMMENT ON COLUMN "DidDocuments"."Deactivated" IS 'Whether the DID has been deactivated';

COMMENT ON COLUMN "DidDocuments"."DeactivatedAt" IS 'When it was deactivated (UTC)';

COMMENT ON COLUMN "DidDocuments"."CreatedAt" IS 'When the DID was created (UTC)';

CREATE TABLE "ExternalCertificateRequests" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "TrustDomainId" INTEGER NOT NULL,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "SubjectDn" CHARACTER VARYING(500) NOT NULL,
    "SubjectAltNamesJson" TEXT,
    "CsrPem" TEXT NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "KeySize" INTEGER NOT NULL,
    "PublicKeyThumbprint" CHARACTER VARYING(64) NOT NULL,
    "EncryptedPrivateKeyPem" TEXT NOT NULL,
    "KeyPassword" CHARACTER VARYING(200) NOT NULL,
    "ExternalCaName" CHARACTER VARYING(200),
    "Notes" TEXT,
    "ModeledOnCertificateId" INTEGER,
    "ModeledOnEntityType" CHARACTER VARYING(40),
    "Profile" INTEGER NOT NULL,
    "Status" INTEGER NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "UpdatedAt" TIMESTAMP WITH TIME ZONE,
    "FulfilledAt" TIMESTAMP WITH TIME ZONE,
    "FulfilledCertificateId" INTEGER,
    "FulfilledEntityType" CHARACTER VARYING(40),
    "FulfilledThumbprint" CHARACTER VARYING(64),
    CONSTRAINT "PK_ExternalCertificateRequests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExternalCertificateRequests_TrustDomains_TrustDomainId" FOREIGN KEY ("TrustDomainId") REFERENCES "TrustDomains" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "ExternalCertificateRequests" IS 'CSRs sent to external CAs, with the private key held until the certificate comes back';

COMMENT ON COLUMN "ExternalCertificateRequests"."Id" IS 'Primary key';

COMMENT ON COLUMN "ExternalCertificateRequests"."TrustDomainId" IS 'Trust domain the returned certificate is imported into (TrustDomains.Id)';

COMMENT ON COLUMN "ExternalCertificateRequests"."Name" IS 'Display name';

COMMENT ON COLUMN "ExternalCertificateRequests"."SubjectDn" IS 'Subject distinguished name requested';

COMMENT ON COLUMN "ExternalCertificateRequests"."SubjectAltNamesJson" IS 'JSON array of {Type, Value} SAN entries placed in the CSR';

COMMENT ON COLUMN "ExternalCertificateRequests"."CsrPem" IS 'PKCS#10 request, PEM encoded, as handed to the external CA';

COMMENT ON COLUMN "ExternalCertificateRequests"."KeyAlgorithm" IS 'Key algorithm of the requested key';

COMMENT ON COLUMN "ExternalCertificateRequests"."KeySize" IS 'Key size in bits for RSA; parameter set number for post-quantum algorithms';

COMMENT ON COLUMN "ExternalCertificateRequests"."PublicKeyThumbprint" IS 'SHA-256 of the SubjectPublicKeyInfo, upper-case hex; matches the returned certificate';

COMMENT ON COLUMN "ExternalCertificateRequests"."EncryptedPrivateKeyPem" IS 'PKCS#8 private key, PEM, encrypted with KeyPassword';

COMMENT ON COLUMN "ExternalCertificateRequests"."KeyPassword" IS 'Password of EncryptedPrivateKeyPem';

COMMENT ON COLUMN "ExternalCertificateRequests"."ExternalCaName" IS 'Free text: which CA the request went to, ticket numbers';

COMMENT ON COLUMN "ExternalCertificateRequests"."Notes" IS 'Operator notes';

COMMENT ON COLUMN "ExternalCertificateRequests"."ModeledOnCertificateId" IS 'Certificate this request renews, for lineage; null for a new request';

COMMENT ON COLUMN "ExternalCertificateRequests"."ModeledOnEntityType" IS 'Table of ModeledOnCertificateId: CaCertificate or IssuedCertificate';

COMMENT ON COLUMN "ExternalCertificateRequests"."Profile" IS 'Requested-extension profile the CSR was built with: 0 None, 1 UdapClient, and so on';

COMMENT ON COLUMN "ExternalCertificateRequests"."Status" IS '0 Pending, 1 Fulfilled, 2 Cancelled';

COMMENT ON COLUMN "ExternalCertificateRequests"."CreatedAt" IS 'When the request was created (UTC)';

COMMENT ON COLUMN "ExternalCertificateRequests"."UpdatedAt" IS 'When the CSR was last regenerated after an edit (UTC); null when never edited';

COMMENT ON COLUMN "ExternalCertificateRequests"."FulfilledAt" IS 'When the returned certificate was imported (UTC)';

COMMENT ON COLUMN "ExternalCertificateRequests"."FulfilledCertificateId" IS 'The imported certificate once fulfilled';

COMMENT ON COLUMN "ExternalCertificateRequests"."FulfilledEntityType" IS 'Table of FulfilledCertificateId: CaCertificate or IssuedCertificate';

COMMENT ON COLUMN "ExternalCertificateRequests"."FulfilledThumbprint" IS 'Thumbprint of the imported certificate';

CREATE TABLE "TrustDomainBaseUrls" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "TrustDomainId" INTEGER NOT NULL,
    "Url" CHARACTER VARYING(500) NOT NULL,
    "SortOrder" INTEGER NOT NULL,
    "PublishingBasePath" CHARACTER VARYING(500),
    CONSTRAINT "PK_TrustDomainBaseUrls" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TrustDomainBaseUrls_TrustDomains_TrustDomainId" FOREIGN KEY ("TrustDomainId") REFERENCES "TrustDomains" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "TrustDomainBaseUrls" IS 'Publication base URLs of a trust domain and where each is published on disk (the repository)';

COMMENT ON COLUMN "TrustDomainBaseUrls"."Id" IS 'Primary key';

COMMENT ON COLUMN "TrustDomainBaseUrls"."TrustDomainId" IS 'Owning trust domain (TrustDomains.Id)';

COMMENT ON COLUMN "TrustDomainBaseUrls"."Url" IS 'Base URL that {BaseUrl} expands to in CDP and AIA URLs';

COMMENT ON COLUMN "TrustDomainBaseUrls"."SortOrder" IS 'Order of the URLs in issued certificates';

COMMENT ON COLUMN "TrustDomainBaseUrls"."PublishingBasePath" IS 'Local folder where CRLs and CA certificates for this URL are written; null when not published locally';

CREATE TABLE "Crls" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "CaCertificateId" INTEGER NOT NULL,
    "CrlNumber" BIGINT NOT NULL,
    "ThisUpdate" TIMESTAMP WITH TIME ZONE NOT NULL,
    "NextUpdate" TIMESTAMP WITH TIME ZONE NOT NULL,
    "SignatureAlgorithm" CHARACTER VARYING(50) NOT NULL,
    "RawBytes" BYTEA NOT NULL,
    "FileName" CHARACTER VARYING(200),
    "SignatureValid" BOOLEAN NOT NULL,
    "IsArchived" BOOLEAN NOT NULL,
    "ArchivedAt" TIMESTAMP WITH TIME ZONE,
    "ImportedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_Crls" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Crls_CaCertificates_CaCertificateId" FOREIGN KEY ("CaCertificateId") REFERENCES "CaCertificates" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "Crls" IS 'Certificate revocation lists issued or imported for a CA';

COMMENT ON COLUMN "Crls"."Id" IS 'Primary key';

COMMENT ON COLUMN "Crls"."CaCertificateId" IS 'Issuing CA (CaCertificates.Id)';

COMMENT ON COLUMN "Crls"."CrlNumber" IS 'CRL number extension value (2.5.29.20)';

COMMENT ON COLUMN "Crls"."ThisUpdate" IS 'When the CRL was issued (UTC)';

COMMENT ON COLUMN "Crls"."NextUpdate" IS 'When the next CRL is due (UTC); drives auto-renewal';

COMMENT ON COLUMN "Crls"."SignatureAlgorithm" IS 'Algorithm the CRL is signed with';

COMMENT ON COLUMN "Crls"."RawBytes" IS 'The CRL, DER encoded';

COMMENT ON COLUMN "Crls"."FileName" IS 'File name for display and download';

COMMENT ON COLUMN "Crls"."SignatureValid" IS 'Whether the signature verified against the issuing CA';

COMMENT ON COLUMN "Crls"."IsArchived" IS 'Superseded CRL kept for history';

COMMENT ON COLUMN "Crls"."ArchivedAt" IS 'When it was archived (UTC)';

COMMENT ON COLUMN "Crls"."ImportedAt" IS 'When the row was created (UTC)';

CREATE TABLE "IssuedCertificates" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "IssuingCaCertificateId" INTEGER NOT NULL,
    "ProfileId" INTEGER,
    "Name" CHARACTER VARYING(200) NOT NULL,
    "Subject" CHARACTER VARYING(500) NOT NULL,
    "SubjectAltNames" TEXT,
    "X509CertificatePem" TEXT NOT NULL,
    "EncryptedPfxBytes" BYTEA,
    "PfxPassword" TEXT,
    "Thumbprint" CHARACTER VARYING(64) NOT NULL,
    "SerialNumber" CHARACTER VARYING(100) NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "KeySize" INTEGER NOT NULL,
    "NotBefore" TIMESTAMP WITH TIME ZONE NOT NULL,
    "NotAfter" TIMESTAMP WITH TIME ZONE NOT NULL,
    "IsRevoked" BOOLEAN NOT NULL,
    "RevokedAt" TIMESTAMP WITH TIME ZONE,
    "RevocationReason" INTEGER NOT NULL,
    "Version" INTEGER NOT NULL,
    "RenewalOfId" INTEGER,
    "CertSecurityLevel" SMALLINT NOT NULL,
    "StoreProviderHint" CHARACTER VARYING(200),
    "Enabled" BOOLEAN NOT NULL,
    "AutoRenew" BOOLEAN NOT NULL,
    "IsArchived" BOOLEAN NOT NULL,
    "ArchivedAt" TIMESTAMP WITH TIME ZONE,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_IssuedCertificates" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_IssuedCertificates_CaCertificates_IssuingCaCertificateId" FOREIGN KEY ("IssuingCaCertificateId") REFERENCES "CaCertificates" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_IssuedCertificates_CertificateProfiles_ProfileId" FOREIGN KEY ("ProfileId") REFERENCES "CertificateProfiles" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_IssuedCertificates_IssuedCertificates_RenewalOfId" FOREIGN KEY ("RenewalOfId") REFERENCES "IssuedCertificates" ("Id") ON DELETE SET NULL
);

COMMENT ON TABLE "IssuedCertificates" IS 'End-entity certificates issued or imported, with their keys';

COMMENT ON COLUMN "IssuedCertificates"."Id" IS 'Primary key';

COMMENT ON COLUMN "IssuedCertificates"."IssuingCaCertificateId" IS 'Issuing CA (CaCertificates.Id)';

COMMENT ON COLUMN "IssuedCertificates"."ProfileId" IS 'Certificate profile used (CertificateProfiles.Id); null for imported certificates';

COMMENT ON COLUMN "IssuedCertificates"."Name" IS 'Display name';

COMMENT ON COLUMN "IssuedCertificates"."Subject" IS 'Subject distinguished name';

COMMENT ON COLUMN "IssuedCertificates"."SubjectAltNames" IS 'Subject alternative names as displayed, e.g. Email:alice@example.org';

COMMENT ON COLUMN "IssuedCertificates"."X509CertificatePem" IS 'The certificate, PEM encoded';

COMMENT ON COLUMN "IssuedCertificates"."EncryptedPfxBytes" IS 'PKCS#12 holding the private key (AES-256); null when the key is not held';

COMMENT ON COLUMN "IssuedCertificates"."PfxPassword" IS 'Password of EncryptedPfxBytes';

COMMENT ON COLUMN "IssuedCertificates"."Thumbprint" IS 'SHA-1 thumbprint, upper-case hex';

COMMENT ON COLUMN "IssuedCertificates"."SerialNumber" IS 'Serial number, hex';

COMMENT ON COLUMN "IssuedCertificates"."KeyAlgorithm" IS 'Key algorithm, e.g. RSA, ECDSA, ML-DSA-87, ML-KEM-1024';

COMMENT ON COLUMN "IssuedCertificates"."KeySize" IS 'Key size in bits for RSA; parameter set number for post-quantum algorithms';

COMMENT ON COLUMN "IssuedCertificates"."NotBefore" IS 'Start of validity (UTC)';

COMMENT ON COLUMN "IssuedCertificates"."NotAfter" IS 'End of validity (UTC)';

COMMENT ON COLUMN "IssuedCertificates"."IsRevoked" IS 'Whether the certificate has been revoked';

COMMENT ON COLUMN "IssuedCertificates"."RevokedAt" IS 'When it was revoked (UTC)';

COMMENT ON COLUMN "IssuedCertificates"."RevocationReason" IS 'CRL reason code (RFC 5280 section 5.3.1)';

COMMENT ON COLUMN "IssuedCertificates"."Version" IS '1-based renewal generation within this certificate lineage; incremented on each re-key';

COMMENT ON COLUMN "IssuedCertificates"."RenewalOfId" IS 'Certificate this one renewed (IssuedCertificates.Id); null for the first issuance';

COMMENT ON COLUMN "IssuedCertificates"."CertSecurityLevel" IS 'Where the key lives: 0 Software, 1 Fips1403 (HSM), 2 CloudKms';

COMMENT ON COLUMN "IssuedCertificates"."StoreProviderHint" IS 'Signing provider and key id for remote keys';

COMMENT ON COLUMN "IssuedCertificates"."Enabled" IS 'Whether the certificate is in use';

COMMENT ON COLUMN "IssuedCertificates"."AutoRenew" IS 'Whether the certificate is renewed automatically; off means left to expire on purpose';

COMMENT ON COLUMN "IssuedCertificates"."IsArchived" IS 'Hidden from the explorer but kept for history';

COMMENT ON COLUMN "IssuedCertificates"."ArchivedAt" IS 'When it was archived (UTC)';

COMMENT ON COLUMN "IssuedCertificates"."CreatedAt" IS 'When the row was created (UTC)';

CREATE TABLE "IssuedCredentials" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "TrustDomainId" INTEGER NOT NULL,
    "CredentialSchemaId" INTEGER NOT NULL,
    "IssuerDidDocumentId" INTEGER NOT NULL,
    "SubjectDid" CHARACTER VARYING(500) NOT NULL,
    "ClaimsJson" TEXT NOT NULL,
    "Format" CHARACTER VARYING(50) NOT NULL,
    "SignedCredential" TEXT NOT NULL,
    "CredentialId" CHARACTER VARYING(200) NOT NULL,
    "IssuedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    "ValidUntil" TIMESTAMP WITH TIME ZONE,
    "Revoked" BOOLEAN NOT NULL,
    "RevokedAt" TIMESTAMP WITH TIME ZONE,
    CONSTRAINT "PK_IssuedCredentials" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_IssuedCredentials_CredentialSchemas_CredentialSchemaId" FOREIGN KEY ("CredentialSchemaId") REFERENCES "CredentialSchemas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_IssuedCredentials_DidDocuments_IssuerDidDocumentId" FOREIGN KEY ("IssuerDidDocumentId") REFERENCES "DidDocuments" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_IssuedCredentials_TrustDomains_TrustDomainId" FOREIGN KEY ("TrustDomainId") REFERENCES "TrustDomains" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "IssuedCredentials" IS 'Verifiable Credentials issued by Sigyll';

COMMENT ON COLUMN "IssuedCredentials"."Id" IS 'Primary key';

COMMENT ON COLUMN "IssuedCredentials"."TrustDomainId" IS 'Owning trust domain (TrustDomains.Id)';

COMMENT ON COLUMN "IssuedCredentials"."CredentialSchemaId" IS 'Schema the claims were validated against (CredentialSchemas.Id)';

COMMENT ON COLUMN "IssuedCredentials"."IssuerDidDocumentId" IS 'Issuing DID (DidDocuments.Id)';

COMMENT ON COLUMN "IssuedCredentials"."SubjectDid" IS 'Subject DID; need not be a DID Sigyll controls';

COMMENT ON COLUMN "IssuedCredentials"."ClaimsJson" IS 'Submitted claims as JSON';

COMMENT ON COLUMN "IssuedCredentials"."Format" IS 'Securing format used, e.g. jwt_vc';

COMMENT ON COLUMN "IssuedCredentials"."SignedCredential" IS 'The signed credential, e.g. a compact JWT';

COMMENT ON COLUMN "IssuedCredentials"."CredentialId" IS 'VC id, e.g. urn:uuid:...';

COMMENT ON COLUMN "IssuedCredentials"."IssuedAt" IS 'When the credential was issued (UTC)';

COMMENT ON COLUMN "IssuedCredentials"."ValidUntil" IS 'End of validity (UTC); null for no expiry';

COMMENT ON COLUMN "IssuedCredentials"."Revoked" IS 'Whether the credential has been revoked';

COMMENT ON COLUMN "IssuedCredentials"."RevokedAt" IS 'When it was revoked (UTC)';

CREATE TABLE "VerificationMethods" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "DidDocumentId" INTEGER NOT NULL,
    "MethodId" CHARACTER VARYING(500) NOT NULL,
    "KeyAlgorithm" CHARACTER VARYING(64) NOT NULL,
    "Provider" CHARACTER VARYING(50) NOT NULL,
    "KeyIdentifier" CHARACTER VARYING(200) NOT NULL,
    "KeySize" INTEGER NOT NULL,
    "PublicKeyMultibase" CHARACTER VARYING(500) NOT NULL,
    "Purposes" CHARACTER VARYING(200) NOT NULL,
    "CreatedAt" TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT "PK_VerificationMethods" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VerificationMethods_DidDocuments_DidDocumentId" FOREIGN KEY ("DidDocumentId") REFERENCES "DidDocuments" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "VerificationMethods" IS 'Keys (verification methods) of a DID document';

COMMENT ON COLUMN "VerificationMethods"."Id" IS 'Primary key';

COMMENT ON COLUMN "VerificationMethods"."DidDocumentId" IS 'Owning DID document (DidDocuments.Id)';

COMMENT ON COLUMN "VerificationMethods"."MethodId" IS 'Full verification method id including fragment, e.g. did:key:z6Mk...#z6Mk...';

COMMENT ON COLUMN "VerificationMethods"."KeyAlgorithm" IS 'Key algorithm, e.g. Ed25519, ECDSA, RSA';

COMMENT ON COLUMN "VerificationMethods"."Provider" IS 'Signing provider holding the key, e.g. local or vault-transit';

COMMENT ON COLUMN "VerificationMethods"."KeyIdentifier" IS 'Key id within the provider';

COMMENT ON COLUMN "VerificationMethods"."KeySize" IS 'Key size in bits where applicable';

COMMENT ON COLUMN "VerificationMethods"."PublicKeyMultibase" IS 'Public key, multibase encoded (z-prefix base58btc)';

COMMENT ON COLUMN "VerificationMethods"."Purposes" IS 'Semicolon-delimited purposes, e.g. assertionMethod;authentication';

COMMENT ON COLUMN "VerificationMethods"."CreatedAt" IS 'When the key was created (UTC)';

CREATE TABLE "CertificateRevocations" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "CrlId" INTEGER NOT NULL,
    "RevokedCertSerialNumber" CHARACTER VARYING(100) NOT NULL,
    "RevokedCertThumbprint" CHARACTER VARYING(64),
    "RevocationDate" TIMESTAMP WITH TIME ZONE NOT NULL,
    "RevocationReason" INTEGER NOT NULL,
    CONSTRAINT "PK_CertificateRevocations" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CertificateRevocations_Crls_CrlId" FOREIGN KEY ("CrlId") REFERENCES "Crls" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "CertificateRevocations" IS 'Revoked-certificate entries read from a CRL';

COMMENT ON COLUMN "CertificateRevocations"."Id" IS 'Primary key';

COMMENT ON COLUMN "CertificateRevocations"."CrlId" IS 'CRL the entry came from (Crls.Id)';

COMMENT ON COLUMN "CertificateRevocations"."RevokedCertSerialNumber" IS 'Serial number of the revoked certificate, hex';

COMMENT ON COLUMN "CertificateRevocations"."RevokedCertThumbprint" IS 'Thumbprint of the revoked certificate when known';

COMMENT ON COLUMN "CertificateRevocations"."RevocationDate" IS 'Revocation date in the CRL entry (UTC)';

COMMENT ON COLUMN "CertificateRevocations"."RevocationReason" IS 'CRL reason code (RFC 5280 section 5.3.1)';

CREATE TABLE "AspNetRoles" (
    "Id" TEXT NOT NULL,
    "Name" CHARACTER VARYING(256),
    "NormalizedName" CHARACTER VARYING(256),
    "ConcurrencyStamp" TEXT,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "AspNetRoles" IS 'ASP.NET Core Identity roles';

COMMENT ON COLUMN "AspNetRoles"."Id" IS 'Primary key (role id)';

COMMENT ON COLUMN "AspNetRoles"."Name" IS 'Role name';

COMMENT ON COLUMN "AspNetRoles"."NormalizedName" IS 'Upper-cased role name used for lookups';

COMMENT ON COLUMN "AspNetRoles"."ConcurrencyStamp" IS 'Random value that changes on every update (optimistic concurrency)';

CREATE TABLE "AspNetUsers" (
    "Id" TEXT NOT NULL,
    "DisplayName" TEXT,
    "UserName" CHARACTER VARYING(256),
    "NormalizedUserName" CHARACTER VARYING(256),
    "Email" CHARACTER VARYING(256),
    "NormalizedEmail" CHARACTER VARYING(256),
    "EmailConfirmed" BOOLEAN NOT NULL,
    "PasswordHash" TEXT,
    "SecurityStamp" TEXT,
    "ConcurrencyStamp" TEXT,
    "PhoneNumber" CHARACTER VARYING(256),
    "PhoneNumberConfirmed" BOOLEAN NOT NULL,
    "TwoFactorEnabled" BOOLEAN NOT NULL,
    "LockoutEnd" TIMESTAMP WITH TIME ZONE,
    "LockoutEnabled" BOOLEAN NOT NULL,
    "AccessFailedCount" INTEGER NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "AspNetUsers" IS 'ASP.NET Core Identity user accounts';

COMMENT ON COLUMN "AspNetUsers"."Id" IS 'Primary key (user id)';

COMMENT ON COLUMN "AspNetUsers"."DisplayName" IS 'Name shown in the UI';

COMMENT ON COLUMN "AspNetUsers"."UserName" IS 'Sign-in name';

COMMENT ON COLUMN "AspNetUsers"."NormalizedUserName" IS 'Upper-cased user name used for lookups';

COMMENT ON COLUMN "AspNetUsers"."Email" IS 'Email address';

COMMENT ON COLUMN "AspNetUsers"."NormalizedEmail" IS 'Upper-cased email used for lookups';

COMMENT ON COLUMN "AspNetUsers"."EmailConfirmed" IS 'Whether the email address has been confirmed';

COMMENT ON COLUMN "AspNetUsers"."PasswordHash" IS 'Salted and hashed password; null for passwordless (passkey-only) accounts';

COMMENT ON COLUMN "AspNetUsers"."SecurityStamp" IS 'Random value that changes when credentials change; invalidates existing sign-ins';

COMMENT ON COLUMN "AspNetUsers"."ConcurrencyStamp" IS 'Random value that changes on every update (optimistic concurrency)';

COMMENT ON COLUMN "AspNetUsers"."PhoneNumber" IS 'Phone number';

COMMENT ON COLUMN "AspNetUsers"."PhoneNumberConfirmed" IS 'Whether the phone number has been confirmed';

COMMENT ON COLUMN "AspNetUsers"."TwoFactorEnabled" IS 'Whether two-factor sign-in is enabled';

COMMENT ON COLUMN "AspNetUsers"."LockoutEnd" IS 'When an active lockout ends; null when not locked out';

COMMENT ON COLUMN "AspNetUsers"."LockoutEnabled" IS 'Whether the account can be locked out after failed sign-ins';

COMMENT ON COLUMN "AspNetUsers"."AccessFailedCount" IS 'Consecutive failed sign-in attempts';

CREATE TABLE "AspNetRoleClaims" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" TEXT NOT NULL,
    "ClaimType" TEXT,
    "ClaimValue" TEXT,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetRoleClaims" IS 'Claims granted to every member of a role';

COMMENT ON COLUMN "AspNetRoleClaims"."Id" IS 'Primary key';

COMMENT ON COLUMN "AspNetRoleClaims"."RoleId" IS 'Role the claim belongs to (AspNetRoles.Id)';

COMMENT ON COLUMN "AspNetRoleClaims"."ClaimType" IS 'Claim type';

COMMENT ON COLUMN "AspNetRoleClaims"."ClaimValue" IS 'Claim value';

CREATE TABLE "AspNetUserClaims" (
    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "UserId" TEXT NOT NULL,
    "ClaimType" TEXT,
    "ClaimValue" TEXT,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserClaims" IS 'Claims held by a user';

COMMENT ON COLUMN "AspNetUserClaims"."Id" IS 'Primary key';

COMMENT ON COLUMN "AspNetUserClaims"."UserId" IS 'User the claim belongs to (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserClaims"."ClaimType" IS 'Claim type';

COMMENT ON COLUMN "AspNetUserClaims"."ClaimValue" IS 'Claim value';

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" CHARACTER VARYING(128) NOT NULL,
    "ProviderKey" CHARACTER VARYING(128) NOT NULL,
    "ProviderDisplayName" TEXT,
    "UserId" TEXT NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserLogins" IS 'External sign-in providers linked to a user';

COMMENT ON COLUMN "AspNetUserLogins"."LoginProvider" IS 'External provider name, e.g. Microsoft or Google';

COMMENT ON COLUMN "AspNetUserLogins"."ProviderKey" IS 'The user''s identifier at the external provider';

COMMENT ON COLUMN "AspNetUserLogins"."ProviderDisplayName" IS 'Provider name shown in the UI';

COMMENT ON COLUMN "AspNetUserLogins"."UserId" IS 'Linked user (AspNetUsers.Id)';

CREATE TABLE "AspNetUserPasskeys" (
    "CredentialId" BYTEA NOT NULL,
    "UserId" TEXT NOT NULL,
    "Data" JSONB NOT NULL,
    CONSTRAINT "PK_AspNetUserPasskeys" PRIMARY KEY ("CredentialId"),
    CONSTRAINT "FK_AspNetUserPasskeys_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserPasskeys" IS 'WebAuthn passkeys registered to a user';

COMMENT ON COLUMN "AspNetUserPasskeys"."CredentialId" IS 'WebAuthn credential id (primary key)';

COMMENT ON COLUMN "AspNetUserPasskeys"."UserId" IS 'Owning user (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserPasskeys"."Data" IS 'Passkey public key and metadata as JSON';

CREATE TABLE "AspNetUserRoles" (
    "UserId" TEXT NOT NULL,
    "RoleId" TEXT NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserRoles" IS 'Role membership of users';

COMMENT ON COLUMN "AspNetUserRoles"."UserId" IS 'Member (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserRoles"."RoleId" IS 'Role (AspNetRoles.Id)';

CREATE TABLE "AspNetUserTokens" (
    "UserId" TEXT NOT NULL,
    "LoginProvider" CHARACTER VARYING(128) NOT NULL,
    "Name" CHARACTER VARYING(128) NOT NULL,
    "Value" TEXT,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

COMMENT ON TABLE "AspNetUserTokens" IS 'Tokens stored for a user, e.g. authenticator keys and recovery codes';

COMMENT ON COLUMN "AspNetUserTokens"."UserId" IS 'Owning user (AspNetUsers.Id)';

COMMENT ON COLUMN "AspNetUserTokens"."LoginProvider" IS 'Provider that issued the token';

COMMENT ON COLUMN "AspNetUserTokens"."Name" IS 'Token name';

COMMENT ON COLUMN "AspNetUserTokens"."Value" IS 'Token value';

